if (typeof module === 'object' && module.exports) {
  var path = require('path')
  var fs = require('fs')
  var templateDir = path.resolve(__dirname, '../../../../app/views/templates/pivottable_email')
  var templateFile = path.join(templateDir, 'html.ejs')
  var templateStr = fs.readFileSync(templateFile, { encoding: 'utf8' })
  var ejs = require('ejs')
  var template = ejs.compile(templateStr, { filename: templateFile })
}

function EmailView (allIssues, routeParams) {
  this.allIssues = allIssues
  this.routeParams = routeParams
}

var fieldValue = function (issue, name, options, value) {
  if (['progress', 'aggregateprogress'].indexOf(name) >= 0) {
    if (!issue.fields.progress) {
      return '&nbsp;'
    } else {
      var actual = issue.fields.progress.progress || 0
      var remaining = issue.fields.progress.total - actual
      return TimesheetUtils.getProgressHtml({ estimate: remaining, timespent: actual })
    }
  } else {
    return HtmlView.prototype.fieldValue(issue, name, options, null, value)
  }
}

var getEntryValue = function (columnName, entry, options, zeroable) {
  var value = ''
  if (['62rate', '7cost'].indexOf(columnName) >= 0) {
    value = HtmlView.currency(entry, options.configOptions.currencySymbol)
  } else if (!entry && entry !== 0) {
  } else if (columnName === '6progress') {
    value = TimesheetUtils.getProgressHtml(entry.value || entry)
  } else if (columnName === '5originalestimateremaining') {
    value = TimesheetUtils.getOriginalEstimateRemainingHtml(entry, options.jiraConfig)
  } else if (['1started', '3action'].indexOf(columnName) >= 0) {
  } else {
    value = TimesheetUtils.prettyHours(entry, options.jiraConfig, options.isElapsedTime, zeroable)
  }
  return value
}

EmailView.prototype.generate = function (options) {
  var pivotTable = PivotTableFactory.createPivotTable(options)
  for (var i in this.allIssues) {
    pivotTable.add(this.allIssues[i])
  }
  if (options.users) {
    options.users.forEach(user => {
      var rowKey = new PivotKey.GroupByField(null, { author: user }, options)
      var entry = new EmptyPivotEntry(rowKey)
      pivotTable.addEntry(entry)
    })
  }
  pivotTable.postProcessPivotTable(options)
  pivotTable.showOnce = []
  pivotTable.sortedColumns()
  pivotTable.sortedRows()
  pivotTable.getMonths(options)
  var gadgetSummary = new GadgetSummary(GadgetSummary.getSelectedOptionLabels(this.routeParams, options, options.translations), options.user, options.pivotTableType, options.translations).getSummaryItems()
  return Promise.resolve(template({
    gadgetSummary,
    pivotTable,
    pivotTableType: options.pivotTableType,
    paramUsersInfo: options.paramUsersInfo,
    compressed: options.compressed,
    rowKeySize: 5,
    hostBaseUrl: options.hostBaseUrl || '',
    translations: options.translations,
    restrictedProjects: options.restrictedProjects && options.restrictedProjects.join(','),
    restrictedGroups: options.restrictedGroups && (options.restrictedGroups.join(',') || 'NONE'),
    restrictionError: null,
    prettyHours: TimesheetUtils.prettyHours,
    jiraConfig: options.jiraConfig,
    isElapsedTime: options.isElapsedTime,
    hideTotalColumn: options.hideTotalColumn,
    showTotalInFront: options.showTotalInFront,
    reportParams: this.routeParams.viewId ? 'viewId=' + this.routeParams.viewId : require('../../../../job/jquery-param')(this.routeParams),
    showDetailsCount: options.showDetailsCount,
    groupByField: options.groupByField,
    moreFieldsOptions: options.moreFieldsOptions,
    orderByOptions: options.orderByOptions,
    pivotByFieldOptions: options.pivotByFieldOptions,
    categorizeByField: options.categorizeByField,
    showCategoryRow: options.configOptions.showCategoryRow,
    allFields: options.allFields,
    numOfWeeks: options.numOfWeeks,
    fieldValue: (issue, name, value) => fieldValue(issue, name, options, value),
    getColumnTitle: (column) => HtmlView.getColumnTitle(column, options),
    getDay: (date) => HtmlView.getDay(date),
    getWeek: (date) => HtmlView.getWeek(date),
    getEntryValue: (columnName, entry, zeroable) => getEntryValue(columnName, entry, options, zeroable),
    moment: moment
  }))
}

if (typeof module === 'object' && module.exports) {
  module.exports = EmailView
  var PivotEntry = require('./PivotEntry')
  var EmptyPivotEntry = PivotEntry.EmptyPivotEntry
  var PivotKey = require('./PivotKey')
  var PivotTableFactory = require('./PivotTable')
  var TimesheetUtils = require('../../timesheetUtils')
  var GadgetSummary = require('../template/GadgetSummary')
  var HtmlView = require('./HtmlView')
  var moment = require('moment-timezone')
}
