const getUrlQueryParam = ({ param, defaultValue }) => {
  const matches = (new RegExp('\\W' + param + '=([^&]+)')).exec(window.location.search)
  const codedParam = matches ? matches[1] : (defaultValue || '')
  return decodeURIComponent(codedParam)
}

if (typeof module === 'object' && module.exports) {
  module.exports = { getUrlQueryParam }
}
