app.directive('pivotCell', ['$compile', function ($compile) {
  return {
    restrict: 'E',
    scope: {
      key: '=',
      columns: '=',
      logWork: '=',
      editWork: '=',
      deleteWork: '=',
      jiraConfig: '=',
      removeCachedWorklog: '='
    },
    link: function (scope, element) {
      if (scope.logWork && scope.key.keyValue === '3action') {
        var column = scope.columns[scope.key.keyValue]
        var html, content
        if (column.isTotalColumn) {
          html = '&nbsp;'
        } else if (column.entries) {
          scope.worklog = { issueKey: column.entries[0].rowKey.keyValue } // new worklog
          column.worklog = scope.worklog // pass to timesheetController#startWork()
          content = `<i class="w-0 p-4 bg-24 bg-no-repeat bg-center"
                          title="{{'Start Work' | i18n}}"
                          style="background-image: url('../images/icon-play.png')"
                          ng-show="$parent.isStartDateToday && !$root.workTimer && key.showStart && !$parent.cannotLogWorkIssue[worklog.issueKey]"
                          ng-click="logWork()">
                      </i>

                      <i class="w-0 p-4 bg-24 bg-no-repeat bg-center"
                          title="{{'Log Work' | i18n}}"
                          style="background-image: url('../images/icon-plus.png')"
                          ng-show="$parent.isStartDateToday && !$root.workTimer && key.showStart && !$parent.cannotLogWorkIssue[worklog.issueKey]"
                          ng-click="$parent.addWorklogDialog(null, worklog.issueKey)">
                      </i>`
          html = $compile(content)(scope)
        } else if (column.worklog && column.worklog.id) {
          scope.worklog = column.worklog
          scope.worklog.issueKey = column.rowKey.keyValue
          scope.worklog.ownWorklog = scope.worklog.author && scope.worklog.author.accountId === scope.$parent.loggedInUser.accountId
          html = $compile('<old-worklog worklog="worklog" edit-work="editWork" delete-work="deleteWork" ' +
                    'cannot-edit="worklog.workDate < $parent.allowToLogFromDate || (worklog.ownWorklog ? $parent.cannotEditOwnWorklogIssue[worklog.issueKey] : $parent.cannotEditAllWorklogIssue[worklog.issueKey])"' +
                    'cannot-delete="worklog.workDate < $parent.allowToLogFromDate || (worklog.ownWorklog ? $parent.cannotDeleteOwnWorklogIssue[worklog.issueKey] : $parent.cannotDeleteAllWorklogIssue[worklog.issueKey])"/>')(scope)
        } else if (!column.worklog.transient) { // new worklog
          scope.entry = column
          scope.worklog = column.worklog
          content = `<new-worklog
                        worklog="worklog"
                        log-work="logWork"
                        entry="entry"
                        remove-cached-worklog = "removeCachedWorklog"
                        disable-suggested = "$parent.disableSuggested" />`
          html = $compile(content)(scope)
        } else { // updatedIssues worklog
          scope.entry = column
          scope.worklog = column.worklog
          content = `<i class="w-0 p-4 bg-24 bg-no-repeat bg-center"
                       ng-click="!$parent.disableSuggested && logWork(false, true, true)"
                       ng-disabled="$parent.disableSuggested"
                       ng-class="{disabled: $parent.disableSuggested}"
                       style="background-image: url('../images/icon-check-pure.png')"
                       title="{{'Save' | i18n}}">
                    </i>

                    <i class="w-0 p-4 bg-24 bg-no-repeat bg-center"
                       style="background-image: url('../images/icon-plus.png')"
                       title="{{'Log Work' | i18n}}"
                       ng-click="logWork(false, true)">
                    </i>`
          html = $compile(content)(scope)
        }
        element.append(html)
      } else if (scope.key.filterName) {
        element.append($compile('<span ng-bind-html="columns[key.keyValue] | ' + scope.key.filterName + '"/>')(scope))
      } else {
        element.append($compile('<span ng-bind="columns[key.keyValue] | prettyHours:jiraConfig:$parent.pivotTableType == \'IssuePassedTimeByStatus\' && !($parent.workingTimeInStatus.from && $parent.workingTimeInStatus.to):columns[key.keyValue]===0"/>')(scope))
      }
    }
  }
}])

app.directive('columnKey', ['$compile', function ($compile) {
  return {
    restrict: 'A',
    scope: {
      columnKey: '='
    },
    link: function (scope, element) {
      scope.$watch('columnKey', function () {
        // FIXME: code duplication
        if (scope.columnKey.user) {
          var href
          var hrefBaseUrl = '{{$parent.hostBaseUrl}}/plugins/servlet/ac/{{$parent.appKey}}/timereports'
          const { viewOptions, viewChanged, userChange } = scope.$parent
          if (scope.$parent.isGadget || element.injector().modules.serverApp) {
            var reportParams = angular.copy(scope.$parent.reportParamsObject)
            delete reportParams.allUsers
            delete reportParams.group
            reportParams.pivotTableType = 'Timesheet'
            reportParams.user = scope.columnKey.user.accountId
            scope.reportParams = (typeof $ !== 'undefined' ? $ : window).param(reportParams, /* traditional */ true)
            // CAUTION: malformated string to be inserted between double quotes
            href = hrefBaseUrl + '#!{{reportParams}}" target="_parent'
          } else {
            scope.startDate = TimesheetUtils.formatDateForSearch(scope.columnKey.options.startDate)
            scope.endDate = TimesheetUtils.formatDateForSearch(scope.columnKey.options.endDate)
            href = hrefBaseUrl + "{{columnKey.user.accountId ? '#!pivotTableType=Timesheet&user=' + columnKey.user.accountId + '&startDate=' + startDate + '&endDate=' + endDate + '&group=' + '&_=' + $id : ''}}" + '"target="_parent'
          }
          element
            .html('<a ng-mouseenter="$parent.userHoverPopup.init(columnKey.user)" ' +
                        'ng-class="{inactive: !columnKey.user.active, disabled: !columnKey.user.accountId, userHoverPopup: true}" ' +
                        'ng-href="' + href + '" ng-bind="columnKey.user.displayName || columnKey.user.name || columnKey.user.accountId"></a>')
            .click(() => {
              viewOptions.selected = 'pivotTableType_Timesheet'
              viewChanged()
              userChange(scope.columnKey.user.accountId)
              return false
            })
          // TODO: element.html(userLink($compile, scope, scope.columnKey.user), /* keepGroupByField */ true);
        } else if (scope.columnKey.date) {
          var html = `
                  <span class="font-semibold text-text-color-1">
                    {{columnKey.date | date:'dd'}}
                  </span>
                  <br>
                  <span class="uppercase font-normal text-text-divider-color-1">
                    {{columnKey.date | date:'EEE' | i18n}}
                  </span>`
          element.html(html)
        } else if (scope.columnKey.weekNumber) {
          scope.startDate = scope.columnKey.firstDate || scope.columnKey.startDate
          scope.endDateIncluded = TimesheetUtils.addDays(scope.columnKey.endDate, -1)
          scope.endDate = scope.columnKey.lastDate || scope.endDateIncluded
          element.html("<span title=\"{{startDate | date:'d'}} {{startDate | date:'MMM' | i18n}}-{{endDate | date:'d'}} {{endDate | date:'MMM' | i18n}}\">{{'Week' | i18n}}<br/>{{columnKey.weekNumber}}</span>")
        } else if (scope.columnKey.monthKey) {
          element.html("<span title=\"{{columnKey.endDate | date:'1-d'}} {{columnKey.endDate | date:'MMM' | i18n}}\">{{columnKey.keyValue | date:'MMM' | i18n}}</span>")
        } else {
          if (['TimeTracking', 'TimeEntry', 'IssueTime', 'CostReport', 'TimeBalance', 'IssueTimeBalance'].indexOf(scope.$parent.pivotTableType) >= 0 || (scope.$parent.pivotTableType === 'Timespent' && !scope.$parent.pivotByField)) {
            // element.html('<span i18n="columnKey.keyValue"></span>')
            element.html(`
                    <table class="w-full">
                      <tr>
                        <td class="text-center">
                          <span i18n="columnKey.keyValue"></span>
                        </td>
                      </tr>
                    </table>`)
          } else if (scope.$parent.pivotTableType === 'Calendar') {
            element.html(`<table class="w-full"
                                 ng-class="{
                                   'border-l-clear': columnKey.order != 0
                                 }">
                            <tr>
                              <td class="text-center">
                                <span i18n="columnKey.day"></span>
                              </td>
                            </tr>
                          </table>`)
          } else {
            // element.html('<span>{{columnKey.keyValue}}</span>')
            // this was done to work with the border left column in the middle of the column
            element.html(`
                    <table class="w-full"
                           ng-class="{
                              'border-l-clear': columnKey.order != 0
                           }">
                      <tr>
                        <td><span></span></td>
                      </tr>
                      <tr>
                        <td class="text-center">
                          <span>{{columnKey.keyValue}}</span>
                        </td>
                      </tr>
                    </table>`)
          }
        }
        $compile(element.contents())(scope)
      })
    }
  }
}])

