app.directive('worklogComment', ['$compile', '$q', function ($compile, $q) {
  return {
    restrict: 'E',
    scope: {
      worklog: '=',
      noComment: '='
    },
    replace: true,
    link: function (scope, element) {
      scope.comment = scope.worklog ? DrawHelper.escapeHtml(scope.worklog.comment) : ''
      var truncatedHtml = $compile('<span title="{{comment.length > 175 ? comment : \'\'}}" ng-bind-html="(comment || noComment | limitTo:175) + (worklog.updated != worklog.created ? \' (<span class=\\\'red\\\'>edited</span>)\' : \'\') | htmlSafe"></span>')(scope)
      var fullHtml = $compile('<span ng-bind-html="comment + (worklog.updated != worklog.created ? \' (<span class=\\\'red\\\'>edited</span>)\' : \'\') | htmlSafe"></span>')(scope)
      if (window.matchMedia) {
        var mediaQueryList = window.matchMedia('print')
        mediaQueryList.addListener(function (mql) {
          if (mql.matches) {
            scope.$apply(function () {
              element.html(fullHtml)
            })
          } else {
            element.html(truncatedHtml)
          }
        })
      }
      element.html(truncatedHtml)
      scope.$watch('worklog.comment', function () {
        scope.comment = scope.worklog ? DrawHelper.escapeHtml(scope.worklog.comment) : ''
        // searching for mention occurrence in worklog comment
        const commentMentionRegex = /\[~accountid:[0-9a-f:\-]+]/g
        var commentMentions = scope.comment ? [...new Set(scope.comment.match(commentMentionRegex))] : null
        if (commentMentions) {
          var promises = []
          commentMentions.forEach(commentMention => {
            var deferred = $q.defer()
            var accountIdParam = commentMention.replace('[~', '')
              .replace('id:', 'Id=')
              .replace(']', '')
            // fetch displayname to replace accountId in comment view
            AP.request({
              url: `/rest/api/3/user?${accountIdParam}`,
              dataType: 'json',
              success: function (data) {
                var user = TimesheetUtils.getJson(data)
                scope.comment = scope.comment.replaceAll(commentMention, '@' + user.displayName)
                deferred.resolve()
                scope.$apply()
              },
              error: function () {
                deferred.reject()
              }
            })
            promises.push(deferred.promise)
          })
          return $q.all(promises)
        }
      })
    }
  }
}])

