app.directive('copyToClipboard', ['translationsSync', function (translations) {
  return {
    restrict: 'A',
    link: function (scope, elem, attrs) {
      elem.click(function () {
        if (attrs.copyToClipboard) {
          window.AP.getLocation(function (location) {
            var copyElement = document.createElement('textarea')
            copyElement.style.position = 'fixed'
            copyElement.style.opacity = '0'
            copyElement.textContent = location + (location.indexOf('#!') < 0 ? '#!' : '&') + attrs.copyToClipboard
            var body = document.getElementsByTagName('body')[0]
            body.appendChild(copyElement)
            copyElement.select()
            document.execCommand('copy')
            body.removeChild(copyElement)
            AP.flag.create({
              title: translations['Copy Link'],
              body: translations['Link Copied'],
              type: 'success',
              close: 'auto'
            })
          })
        }
      })
    }
  }
}])

