const initializeApp = async () => {
  const [location, context, loggedInUserLocale] = await Promise.all([
    getLocation(),
    getJiraContext(),
    getLocale()
  ])

  window.loggedInUserLocale = loggedInUserLocale

  const baseUrl = extractBaseUrl(location)
  window.baseUrl = baseUrl

  if (!window.loggerUrl) return // tests

  const buildNumber = `?_=${getBuildNumber()}`
  window.buildNumber = buildNumber

  try {
    window.featureFlagLaunchDarkly = new FeatureFlagLaunchDarkly(baseUrl, window.INITIAL_STATE.LAUNCH_DARKLY_CLIENT_SIDE_KEY)
    window.hasFeatureFlagImportTTLData = await window.featureFlagLaunchDarkly.getFlag('import-ttl-data')
    window.hasFeatureFlagTtlDeprecationBanner = await window.featureFlagLaunchDarkly.getFlag('ttl-deprecation-banner')
    window.hasFFAtlassianPropertiesMigration = await window.featureFlagLaunchDarkly.getFlag('atlassian-properties-migration')
  } catch (error) {
    console.log('Error initializing LaunchDarkly', error)
  }

  const isConfigurationPage = getUrlQueryParam({ param: 'configuration' })
  const isMainTimesheetPageFromFilter = getUrlQueryParam({ param: 'timesheet-from-filter' })
  const isMainTimesheetPage = getUrlQueryParam({ param: 'timesheet' })
  const isTimesheetInProjectPage = getUrlQueryParam({ param: 'timesheet-in-project' })
  const isJiraIssueContent = getUrlQueryParam({ param: 'jira-issue-content' })
  const isTimereportsInReport = getUrlQueryParam({ param: 'timereports-in-report' })
  const isTimesheetPages = isMainTimesheetPage || isTimesheetInProjectPage
  var isWelcome = getUrlQueryParam({ param: 'welcome' })
  var isIssueTimeBalance = getUrlQueryParam({ param: 'issuetimebalance' })
  var dashboard = context.jira && context.jira.dashboard ? context.jira.dashboard.id : null
  var dashboardItem = context.jira && context.jira.dashboardItem ? context.jira.dashboardItem.id : null
  var issueKey = context.jira && context.jira.issue ? context.jira.issue.key : null
  var issueId = context.jira && context.jira.issue ? context.jira.issue.id : null
  var projectKey = context.jira && context.jira.project ? context.jira.project.key : null
  var isGadget = !!dashboard || !!issueKey
  var dialog = getUrlQueryParam({ param: 'dialog' })
  var license = context.license && context.license.active ? 'active' : 'none' // FIXME: expired?

  var v = getUrlQueryParam({ param: 'v', defaultValue: '1' }) // app version
  if (v === '1') { // TODO: remove
    delete window.mailerUrl
  }

  // FIXME: dashboardItemId, license, hostBaseUrl
  var params = {
    isGadget: isGadget,
    dashboardId: dashboard,
    dashboardItemId: dashboardItem,
    issueKey: issueKey,
    issueId: issueId,
    license: license,
    hostBaseUrl: baseUrl,
    projectKey: projectKey
  }

  if (isIssueTimeBalance) {
    params.issueTimeBalance = true
  }

  // add your jira env here to send emails
  const envWithoutLicence = ['renato-tt-forge-qa', 'timesheets-qa-aws', 'timesheets-qa', 'timereports', 'timesheets-prd-aws']
  let localInstance = false

  if (params.license === 'none') {
    var tenantName = baseUrl.match(/https:\/\/(.+?)\./)[1]
    if (envWithoutLicence.indexOf(tenantName) >= 0) {
      localInstance = true
      params.license = 'active'
    }
  }

  var connectUrl = getUrlQueryParam({ param: 'legacy-connect-url' })
  if (connectUrl && connectUrl === 'true') {
    try {
      const forgeUrl = await getForgeUrl({ location, localInstance })
      AP.navigator.go('site', {
        relativeUrl: forgeUrl
      })
    } catch (error) {
      console.error('Error redirecting to Forge URL', error)
    }
  }

  if (v === '3' && params.license === 'active') {
    params.subscribe = true
  }

  if (v === '3') {
    params.appKey = 'jira-timesheet-plugin'
    params.appName = 'Time Tracker'
    params.appNameShort = 'Time Tracker'
    params.sitePrimeTimesheet = 'cloud'
  } else {
    window.isTimesheet = false
    params.appKey = 'timereports'
    params.appName = 'Time Tracker Lite'
    params.appNameShort = 'Time Tracker Lite'
    params.sitePrimeTimesheet = 'timereports'
  }
  window.isTimesheet = v === '3'
  window.appName = params.appName
  window.appKey = params.appKey

  if (isWelcome) {
    window.mainController = 'WelcomeController'
    window.mainTemplate = `/templates/mainShort.html${buildNumber}`
    params.templates = {
      welcome: `/templates/welcome.html${buildNumber}`
    }
    params.isWelcome = true
  } else if (isConfigurationPage) {
    window.mainController = 'ConfigurationController'
    window.mainTemplate = `/templates/mainShort.html${buildNumber}`
    params.templates = {
      menu: `/templates/configMenu.html${buildNumber}`,
      configure: `/templates/configure.html${buildNumber}`
    }
  } else if (dialog) {
    switch (dialog) {
      case 'timereports':
        window.mainController = 'TimesheetController'
        window.mainTemplate = `/templates/main.html${buildNumber}`
        params.isGadget = true
        params.reportDialog = true
        params.templates = {
          menu: `templates/menu.html${buildNumber}`
        }
        break
      case 'bitbucket':
        window.mainController = 'BitbucketController'
        window.mainTemplate = `/templates/dialogs/bitbucket.html${buildNumber}`
        break
      case 'createworklog':
        window.mainController = 'TimesheetController'
        window.mainTemplate = `/templates/main.html${buildNumber}`
        params.createWorklog = true
        params.isGadget = true
        params.issueKey = issueKey
        params.templates = {}
        break
    }
  } else {
    window.mainController = 'TimesheetController'
    window.mainTemplate = `/templates/main.html${buildNumber}`
    params.templates = {
      menu: `/templates/menu.html${buildNumber}`,
      reportSummary: `/templates/reportSummary.html${buildNumber}`,
      pivottable: `/templates/pivottable.html${buildNumber}`,
      piechart: `/templates/pieChart.html${buildNumber}`,
      timesheet: `/templates/timesheet.html${buildNumber}`,
      issuetimebalance: `/templates/issuetimebalance.html${buildNumber}`,
      issuetime: `/templates/issuetime.html${buildNumber}`,
      calendar: `/templates/calendar.html${buildNumber}`,
      addWorklog: `/templates/popups/addWorklog.html${buildNumber}`,
      editWorklog: `/templates/popups/editWorklog.html${buildNumber}`,
      subscribe: `/templates/popups/subscribe.html${buildNumber}`,
      gadgetConfig: `/templates/gadgetConfig.html${buildNumber}`,
      userPreferences: `/templates/dialogs/userPreferences.html${buildNumber}`,
      hourlyRates: `/templates/dialogs/hourlyRates.html${buildNumber}`
    }
  }
  window.i18nDefault = `/i18n/default.json${buildNumber}`

  const isDialog = !!dialog

  const view = {
    isTimesheetPages,
    isMainTimesheetPageFromFilter,
    isConfigurationPage,
    isJiraIssueContent,
    isTimereportsInReport,
    isTimesheetInProjectPage,
    isGadget,
    isDialog,
    isWelcome
  }

  if (dialog) {
    AP.dialog.getButton('submit').disable()
  }
  $(function () {
    AP.requestBak = AP.request
    AP.request = apRequestWithRetryOptions
    $('body').css('background', '#fff')
    if (isGadget || dialog) {
      $('body').addClass('is-gadget')
    } else {
      $('body').addClass('is-not-gadget')
    }
    if (isWelcome) {
      $('body').addClass('is-welcome')
    }
    $('#content').html("<context items='" + JSON.stringify(params) + "' />")

    const renderWithNewConfiguration = async () => {
      const userInfo = await getUserInfo()

      if (!canAccessApp({ userInfo, view, projectKey, dialog })) {
        renderNoPermission({ isTimesheetPages, isConfigurationPage, isDialog })
        AP.resize('100%', '0')
        return
      }
      angular.bootstrap(document, ['timesheetApp'])
    }

    if (window.isTimesheet) {
      renderWithNewConfiguration()
      return
    }
    // time reports
    angular.bootstrap(document, ['timesheetApp'])
  })
}

initializeApp()
