app.controller('InvoiceDialogController', ['$scope', '$modalInstance', 'invoice',
  function ($scope, $modalInstance, invoice) {
    $scope.invoice = invoice
    $scope.cancel = function () {
      $modalInstance.dismiss()
    }
    $scope.save = function (doExport) {
      $modalInstance.close(doExport)
    }
  }
])
