// eslint-disable-next-line no-unused-vars
function GadgetSummary (selectedOption, users, pivotTableType, translations) {
  var getItemsByKey = function (key, labelSuffix) {
    var result = []
    for (var i = 0; i < selectedOption.length; i++) {
      if (selectedOption[i].key === key && (labelSuffix == null || labelSuffix === /[^.]*$/.exec(selectedOption[i].label)[0])) {
        result.push(selectedOption[i])
      }
    }
    return result
  }

  var getItemValue = function (items) {
    var result = ''
    for (var i = 0; i < items.length; i++) {
      if (result.length > 0) {
        result += ', '
      }
      result += items[i].labelParam
    }
    return result
  }

  var createSummaryItem = function (text, styleClass) {
    return {
      text: text,
      styleClass: styleClass
    }
  }

  this.getSummaryItems = function () {
    var result = []
    result.push(createSummaryItem(translations['Summary '], 'grey'))

    var allUsers = getItemValue(getItemsByKey('allUsers'))
    var value_group = getItemValue(getItemsByKey('group'))
    var value_user = pivotTableType === 'IssueTime' ? users[0].displayName : getItemValue(getItemsByKey('user')) || (users && users[0].displayName)
    var value_excludeGroups = getItemValue(getItemsByKey('excludeGroup'))
    var value_project = getItemValue(getItemsByKey('filterOrProjectId', 'project'))
    var value_filter = getItemValue(getItemsByKey('filterOrProjectId', 'filter'))
    var value_childrenFilter = getItemValue(getItemsByKey('childrenFilterId'))
    var value_workLabelsFilter = getItemValue(getItemsByKey('worklogFilter', 'workLabelsFilter'))
    var value_workAttributesFilter = getItemValue(getItemsByKey('worklogFilter', 'workAttributesFilter'))
    var value_commentFirstWordFilter = getItemValue(getItemsByKey('worklogFilter', 'commentFirstWordFilter'))
    var value_billableFilter = getItemValue(getItemsByKey('billableFilter'))
    var value_startDate = getItemValue(getItemsByKey('startDate'))
    var value_endDate = getItemValue(getItemsByKey('endDate'))
    var value_groupedBy = getItemValue(getItemsByKey('groupByField'))
    var value_categorizeBy = getItemValue(getItemsByKey('categorizeByField'))
    var value_orderedBy = getItemValue(getItemsByKey('orderByField'))

    if ((allUsers && ['Timesheet', 'Calendar', 'PieChart'].indexOf(pivotTableType) >= 0) ||
        (!users && !value_group)) {
      result.push(createSummaryItem(translations['for all users'], 'grey'))
    } else if (value_group) {
      result.push(createSummaryItem(translations['for groups'], 'grey'))
      result.push(createSummaryItem(value_group))
    } else if (users) {
      result.push(createSummaryItem(translations['for user'], 'grey'))
      result.push(createSummaryItem(value_user))
    }
    if (value_excludeGroups) {
      result.push(createSummaryItem(translations['exclude groups'], 'grey'))
      result.push(createSummaryItem(value_excludeGroups))
    }
    if (value_project) {
      if (result.length > 1) {
        result.push(createSummaryItem(translations['and'], 'grey'))
      } else {
        result.push(createSummaryItem(translations['for'], 'grey'))
      }
      result.push(createSummaryItem(translations['project '], 'grey'))
      result.push(createSummaryItem(value_project))
    } else if (pivotTableType === 'IssueTime') {
    } else if (!value_filter && ['Timesheet', 'PieChart'].indexOf(pivotTableType) < 0) {
      if (result.length > 1) {
        result.push(createSummaryItem(translations['and'], 'grey'))
      } else {
        result.push(createSummaryItem(translations['for'], 'grey'))
      }
      result.push(createSummaryItem(translations['all projects']))
    }
    if (value_filter) {
      if (result.length > 1) {
        result.push(createSummaryItem(translations['and'], 'grey'))
      }
      result.push(createSummaryItem(translations['filter'], 'grey'))
      result.push(createSummaryItem(value_filter))
    }
    if (value_childrenFilter) {
      result.push(createSummaryItem(translations['children filter'], 'grey'))
      result.push(createSummaryItem(value_childrenFilter))
    }
    if (value_workLabelsFilter) {
      result.push(createSummaryItem(translations['work labels filter'], 'grey'))
      result.push(createSummaryItem(value_workLabelsFilter))
    }
    if (value_workAttributesFilter) {
      result.push(createSummaryItem(translations['work attributes filter'], 'grey'))
      result.push(createSummaryItem(value_workAttributesFilter))
    }
    if (value_commentFirstWordFilter) {
      result.push(createSummaryItem(translations['comment first word filter'], 'grey'))
      result.push(createSummaryItem(value_commentFirstWordFilter))
    }
    if (value_billableFilter) {
      result.push(createSummaryItem(translations['billable filter'], 'grey'))
      result.push(createSummaryItem(translations[value_billableFilter]))
    }
    if (value_groupedBy) {
      result.push(createSummaryItem(translations['grouped by'], 'grey'))
      result.push(createSummaryItem(value_groupedBy))
    }
    if (value_categorizeBy) {
      result.push(createSummaryItem(translations['categorized by'], 'grey'))
      result.push(createSummaryItem(value_categorizeBy))
    }
    if (value_startDate || value_endDate) {
      if (value_startDate) {
        result.push(createSummaryItem(translations['from'], 'grey'))
        result.push(createSummaryItem(value_startDate))
      }
      if (value_endDate) {
        result.push(createSummaryItem(translations['to'], 'grey'))
        result.push(createSummaryItem(value_endDate))
      }
    } else if (pivotTableType !== 'IssueTime') {
      result.push(createSummaryItem(translations['param.numOfWeeks'].toLowerCase()))
    }
    if (value_orderedBy) {
      result.push(createSummaryItem(translations['ordered by'], 'grey'))
      result.push(createSummaryItem(value_orderedBy))
    }
    return result
  }
}

GadgetSummary.getSelectedOptionLabels = function (routeParams, options, translations) {
  var result = []
  if (options.issueKey && options.issueTimeOptions && options.issueTimeOptions.selected === 'view_-1') {
    return result
  }
  var startDate = (options.startDate && options.startDate.value) || options.startDate
  var endDate = (options.endDate && options.endDate.value) || options.endDate
  var numOfWeeks = (options.numOfWeeks && options.numOfWeeks.value) || options.numOfWeeks
  var keys = Object.keys(routeParams)
  var addToResult = function (key, value, css) {
    var i18nParam = 'param.' + key
    var valueUnique
    if (key === 'filterOrProjectId') {
      if (value.indexOf('project_') === 0) {
        i18nParam += '.project'
      } else if (value.indexOf('filter_') === 0 || value.indexOf('jql_') === 0) {
        i18nParam += '.filter'
      }
      var option = options.filterByOptions.findOption(value)
      value = option ? option.label : value.split('_')[1] || value
    } else if (key === 'worklogFilter') {
      if (value.charAt(0) === '#') {
        i18nParam += '.workLabelsFilter'
      } else if (value.charAt(0) === '@') {
        i18nParam += '.workAttributesFilter'
      } else {
        i18nParam += '.commentFirstWordFilter'
        value = value.toLowerCase()
      }
    } else if (key === 'childrenFilterId') {
      var option = options.childrenFilterOptions.findOption(value)
      if (option != null) {
        value = option.label
      }
    } else if (key === 'groupByField') {
      var option = options.groupByOptions.findOption(value)
      if (option != null) {
        value = option.label
      }
    } else if (key === 'categorizeByField') {
      var option = options.categorizeByOptions.findOption(value)
      if (option != null) {
        value = option.label
      }
    } else if (key === 'moreFields') {
      var option = options.moreFieldsOptions.findOption(value)
      if (option != null) {
        value = option.label
      }
    } else if (key === 'orderByField') {
      var option = options.orderByOptions.findOption(value)
      if (option != null) {
        value = option.label
      }
      if (options.orderDirection === -1) {
        value += ' DESC'
      }
    } else if (key === 'user') {
      valueUnique = value
      value = TimesheetUtils.findByProperty('accountId', value, options.paramUsersInfo)
      value = value && value.displayName
    } else if (key === 'startDate' || key === 'endDate') {
      value = moment(value).format('YYYY-MM-DD') // TODO: format('l') along with date picker
    } else if (key === 'reportingDay') {
      value = value === -1 ? translations['Today']
        : moment.localeData().weekdays(moment().day(parseInt(value)))
    } else if (key === 'jql') {
      value = decodeURIComponent(TimesheetUtils.replaceAll(value, '+', ' '))
    }
    result.push({
      css: css,
      label: i18nParam,
      labelParam: value,
      labelParamUnique: valueUnique,
      key: key
    })
  }
  for (var i = 0; i < keys.length; i++) {
    var key = keys[i]
    if (['user', 'allUsers', 'startDate', 'endDate', 'groupByField', 'categorizeByField', 'moreFields',
      'orderByField', 'filterOrProjectId', 'childrenFilterId', 'worklogFilter', 'billableFilter', 'group', 'excludeGroup',
      'reportingDay', 'jql', 'numOfWeeks'].indexOf(key) < 0) {
      continue
    } else if (key === 'childrenFilterId' && !options.showChildrenFilter) {
      continue
    } else if (key === 'endDate' && (options.pivotTableType === 'TimeEntry' || options.isDayView)) {
      continue
    } else if (key === 'allUsers' && ['Timesheet', 'Timespent', 'CostReport', 'PieChart', 'Calendar'].indexOf(options.pivotTableType) < 0) {
      continue
    } else if (key === 'user' && !options.paramUsersInfo) { // optional user
      continue
    } else if (key === 'moreFields' && options.pivotTableType === 'PieChart') {
      continue
    } else if (key === 'reportingDay' && options.pivotTableType !== 'Timesheet') {
      continue
    } else if (['TimeTracking', 'IssuePassedTimeByStatus'].indexOf(options.pivotTableType) >= 0 && key === 'groupByField' && ['workeduser', 'workeddate', 'workcreated'].indexOf(routeParams[key]) >= 0) {
      continue
    } else if (['Timespent', 'CostReport', 'IssueWorkedTimeByUser', 'IssueWorkedTimeByStatus'].indexOf(options.pivotTableType) < 0 && key === 'groupByField' && ['workedweek'].indexOf(routeParams[key]) >= 0) {
      continue
    } else if ((routeParams.allUsers && key === 'user') || (routeParams.allUsers && key === 'group')) {
      continue
    } else if (routeParams[key] == null && key !== 'numOfWeeks') { // ignore empty params
      continue
    } else if (['group', 'groupByField', 'categorizeByField', 'allUsers'].indexOf(key) >= 0 && !routeParams[key]) {
      continue
    } else if (options.pivotTableType === 'TimeEntry' && ['group', 'allUsers', 'groupByField'].indexOf(key) >= 0) {
      continue
    } else if (options.pivotTableType === 'Calendar' && ['groupByField'].indexOf(key) >= 0) {
      continue
    } else if (key === 'numOfWeeks' && numOfWeeks) {
      continue
    } else if (key === 'worklogFilter' &&
      ['Timesheet', 'IssueWorkedTimeByUser', 'IssueWorkedTimeByStatus', 'IssueWorkedTimeByLabel', 'Timespent',
        'CostReport', 'Calendar'].indexOf(options.pivotTableType) < 0) {
      continue
    } else if (key === 'billableFilter' && (!options.configOptions.tempoToken.val ||
      ['Timesheet', 'IssueWorkedTimeByUser', 'IssueWorkedTimeByStatus', 'IssueWorkedTimeByLabel', 'Timespent',
        'CostReport', 'Calendar'].indexOf(options.pivotTableType) < 0)) {
      continue
    }
    var value = routeParams[key]
    if (key === 'user' && value) {
      value = value.split(',')
    }
    if (Array.isArray(value)) {
      for (var j = 0; j < value.length; j++) {
        addToResult(key, value[j])
      }
    } else if (value) {
      addToResult(key, value)
    } else if (key === 'jql') { // empty JQL
      addToResult(key, value)
    } else if (key === 'numOfWeeks' && !startDate && !endDate &&
      ['Timesheet', 'TimeEntry', 'IssueTime'].indexOf(options.pivotTableType) < 0) { // all time
      addToResult(key, value)
    }
  }
  if (!routeParams.user && !routeParams.allUsers && (!routeParams.group || !routeParams.group.length) && ['Timesheet', 'Timespent', 'CostReport', 'PieChart', 'Calendar'].indexOf(options.pivotTableType) >= 0) {
    addToResult('user', options.loggedInUser.accountId)
  }
  if (!routeParams.filterOrProjectId && options.projectKey && !routeParams._allProjects) {
    addToResult('filterOrProjectId', 'project_' + options.projectKey)
  }
  if (routeParams.startDate === undefined && numOfWeeks) {
    addToResult('startDate', startDate, 'inactive')
  } else if (routeParams.startDate === null) {
    addToResult('startDate', moment('1970-01-01'))
  }
  if (options.pivotTableType !== 'TimeEntry' && !options.isDayView) {
    if (routeParams.endDate === undefined && numOfWeeks) {
      addToResult('endDate', endDate, 'inactive')
    } else if (routeParams.endDate === null) {
      addToResult('endDate', moment('2099-12-31'))
    }
  }
  return result
}

if (typeof module === 'object' && module.exports) {
  module.exports = GadgetSummary
  var moment = require('moment-timezone')
  var TimesheetUtils = require('../../timesheetUtils')
}
