app.controller('DeprecationDialogController', ['$window', '$scope', '$interval', function ($window, $scope, $interval) {
  $scope.showDeprecationDialog = !$window.isTimesheet && window.hasFeatureFlagTtlDeprecationBanner
  /**
   * Get the days until the deprecation date - February 1, 2025
   * @returns {number}
   */
  $scope.getDeprecationTimeRemainingInDays = function () {
    const deprecationDate = moment('2025-02-01')
    const now = moment()
    const duration = moment.duration(deprecationDate.diff(now))
    return Math.round(duration.asDays())
  }

  $scope.acknowledgeDeprecationDialog = () => {
    $scope.showDeprecationDialog = false
  }
}])
