class FeatureFlagLaunchDarkly {
  constructor (baseUrl, LAUNCH_DARKLY_CLIENT_SIDE_KEY) {
    this.baseUrl = baseUrl
    this.LAUNCH_DARKLY_CLIENT_SIDE_KEY = LAUNCH_DARKLY_CLIENT_SIDE_KEY
    const context = {
      kind: 'user',
      key: baseUrl
    }

    this.ldClient = LDClient.initialize(LAUNCH_DARKLY_CLIENT_SIDE_KEY, context)
  }

  async getFlag (flagKey) {
    if (!(await this.waitForInit())) {
      return undefined
    }
    return Boolean(await this.ldClient.variation(flagKey, false))
  }

  async waitForInit () {
    if (!this.ldClient) {
      return false
    }
    await this.ldClient.waitForInitialization().catch(() => {
      this.ldClient = undefined
    })
    return this.ldClient
  };
}

if (typeof module === 'object' && module.exports) {
  module.exports = { FeatureFlagLaunchDarkly }
}
