const getJiraPermissionsAPI = (permission) => {
  const query = `?permissions=${permission}`
  return new Promise((resolve) => {
    AP.request({
      url: `/rest/api/2/mypermissions${query}`,
      cache: true,
      contentType: 'application/json',
      success: (data) => {
        const parsedData = JSON.parse(data)
        var parsedPermissions = parsedData.permissions || []
        resolve(parsedPermissions[permission] && parsedPermissions[permission].havePermission)
      }
    })
  })
}

if (typeof module === 'object' && module.exports) {
  module.exports = { getJiraPermissionsAPI }
}
